struct Node {
    Node(N index, double x_, double y_) : i(index), x(x_), y(y_) {}
    Node(const Node&) = delete;
    Node& operator=(const Node&) = delete;
    Node(Node&&) = delete;
    Node& operator=(Node&&) = delete;

    // vertex index in coordinates array
    const N i;

    // vertex coordinates
    const double x;
    const double y;

    // previous and next vertex nodes in a polygon ring
    Node* prev = nullptr;
    Node* next = nullptr;

    // z-order curve value
    int32_t z = 0;

    // previous and next nodes in z-order
    Node* prevZ = nullptr;
    Node* nextZ = nullptr;

    // indicates whether this is a steiner point
    bool steiner = false;
};

// signed area of a triangle
template <typename N>
double Earcut<N>::area(const Node* p, const Node* q, const Node* r) const {
    return (q->y - p->y) * (r->x - q->x) - (q->x - p->x) * (r->y - q->y);
}

// check if two points are equal
template <typename N>
bool Earcut<N>::equals(const Node* p1, const Node* p2) {
    return p1->x == p2->x && p1->y == p2->y;
}

// check if a point lies within a convex triangle
template <typename N>
bool Earcut<N>::pointInTriangle(double ax, double ay, double bx, double by,
                                double cx, double cy, double px, double py) const {
    return (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0 &&
           (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0 &&
           (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0;
}

template <typename N>
int Earcut<N>::sign(double val) {
    return (0.0 < val) - (val < 0.0);
}

// for collinear points p, q, r, check if point q lies on segment pr
template <typename N>
bool Earcut<N>::onSegment(const Node* p, const Node* q, const Node* r) {
    return q->x <= std::max<double>(p->x, r->x) &&
           q->x >= std::min<double>(p->x, r->x) &&
           q->y <= std::max<double>(p->y, r->y) &&
           q->y >= std::min<double>(p->y, r->y);
}

// check if two segments intersect
template <typename N>
bool Earcut<N>::intersects(const Node* p1, const Node* q1, const Node* p2, const Node* q2) {
    int o1 = sign(area(p1, q1, p2));
    int o2 = sign(area(p1, q1, q2));
    int o3 = sign(area(p2, q2, p1));
    int o4 = sign(area(p2, q2, q1));

    if (o1 != o2 && o3 != o4) return true; // general case

    if (o1 == 0 && onSegment(p1, p2, q1)) return true; // p1, q1 and p2 are collinear and p2 lies on p1q1
    if (o2 == 0 && onSegment(p1, q2, q1)) return true; // p1, q1 and q2 are collinear and q2 lies on p1q1
    if (o3 == 0 && onSegment(p2, p1, q2)) return true; // p2, q2 and p1 are collinear and p1 lies on p2q2
    if (o4 == 0 && onSegment(p2, q1, q2)) return true; // p2, q2 and q1 are collinear and q1 lies on p2q2

    return false;
}

functions.notes:
All four orientations o1..o4 are computed UP FRONT (no short-circuit), in the order p2, q2 against segment (p1,q1), then p1, q1 against segment (p2,q2). Then the general case, then the four collinear cases in order o1,o2,o3,o4. Note the onSegment argument order in each: the queried point is the MIDDLE argument, and the segment endpoints are 1st and 3rd — onSegment(p1, p2, q1) means 'p2 lies within box(p1,q1)'. This version returns TRUE for shared endpoints / touching segments; callers (intersectsPolygon) exclude edges that share an index with a or b, so that is intentional.

OLDER VARIANT (earcut.hpp 0.x through 2.1.x, earcut.js <= 2.1.5) — special equals-endpoints check first, then a strict XOR of two orientation pairs:

    template <typename N>
    bool Earcut<N>::intersects(const Node* p1, const Node* q1, const Node* p2, const Node* q2) {
        if ((equals(p1, q1) && equals(p2, q2)) ||
            (equals(p1, q2) && equals(p2, q1))) return true;
        return (area(p1, q1, p2) > 0) != (area(p1, q1, q2) > 0) &&
               (area(p2, q2, p1) > 0) != (area(p2, q2, q1) > 0);
    }

In that older form the guard is: if the two segments are the SAME segment (in either direction), report intersection; otherwise strict proper-crossing test using `> 0` booleans compared with != (JS used !==). Note `area(...) > 0` groups zero with the negative side, so collinear/touching configurations mostly return false there — that is exactly the robustness hole the 2.2.0 rewrite (sign + onSegment) closed. If you are targeting 2.2.4, use the o1..o4 version; if targeting 2.1.x or the older 0.12.x header, use the equals-first version.

